<script setup lang="ts">
import {
  IonButton,
  IonContent,
  IonInput,
  IonPage,
  IonTextarea,
  useIonRouter,
} from '@ionic/vue'

import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'
import CharacterSettingTip from './modal/CharacterSettingTip.vue'
import CommonHeader from '@/components/CommonHeader.vue'

import RightArrowIcon from '@/components/svg/RightArrowIcon.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import type { Character, EditCharacter } from '@/types'
import { characterService } from '@/services/character'
import type {
  CharacterVoiceModel,
  UpdateCharacterPayload,
} from '@/types/character'
import SignedImg from '@/components/SignedImg.vue'
import { usePolling } from '@/composables/usePolling'
import LoadingLottie from '@/components/LoadingLottie.vue'
import { useToastStore } from '@/store/toast'

const ionRouter = useIonRouter()
const toastStore = useToastStore()
const createUniverseStore = useCreateUniverseStore()
const { inEditCharacter } = storeToRefs(createUniverseStore)

const charVoiceModel = ref<CharacterVoiceModel>()

// 用户reset pose的图片需要讲inEditCharacter的pose.original传入
const originalCharPose = ref<string | undefined>()
const oldChar = ref<Character>()

const { pollingData, startPolling, stopPolling } = usePolling<Character>()
const loading = computed(() => !inEditCharacter.value?.complete)
const charId = inEditCharacter.value!.charId

onMounted(() => {
  oldChar.value = createUniverseStore.generatedUniverse?.chars.find(
    char => char.charId === charId,
  )
  // fetch the voice name by its id in character model
  fetchCharacterVoice()

  // start polling
  startPolling(() => characterService.getCharacterById(charId), 2000)
})

onUnmounted(() => {
  stopPolling()
})

// Watch for the polling data
watch(
  () => pollingData.value,
  (newChar) => {
    if (newChar) {
      if (newChar && newChar.complete) {
        // 把newChar.pose.original放到originalCharPose里
        if (newChar.pose?.original) {
          originalCharPose.value = newChar.pose.original
        }

        fetchCharacterVoice()

        createUniverseStore.updateInEditCharacter({
          charId: newChar.charId,
          charName: inEditCharacter.value?.charName || newChar.charName,
          charDescription:
            inEditCharacter.value?.charDescription || newChar.charDescription,
          complete: newChar.complete,
        })
        stopPolling()
      }
    }
  },
)

watch(
  () => inEditCharacter.value?.voice,
  (newVoiceId) => {
    if (newVoiceId) {
      fetchCharacterVoice()
    }
  },
)

// Get the voice information
async function fetchCharacterVoice() {
  // fetch the voice information from the server
  // and save it to the store
  try {
    const voiceId = inEditCharacter.value?.voice || oldChar.value?.voice

    if (voiceId) {
      const res = await characterService.fetchVoiceById(voiceId)
      if (res) {
        charVoiceModel.value = res
      }
    }
  }
  catch (err) {
    console.error(err)
  }
}

async function saveEdit() {
  await updateChar(charId, inEditCharacter.value!)
  ionRouter.back()
}

async function updateChar(charId: number, newChar: EditCharacter) {
  try {
    const updatePayload: UpdateCharacterPayload = {
      charId,
      updateInfo: {},
    }

    if (newChar.charName) {
      updatePayload.updateInfo.charName = inEditCharacter.value!.charName
    }

    if (newChar.charDescription) {
      updatePayload.updateInfo.charDescription = inEditCharacter.value!.charDescription
    }

    if (newChar.pose) {
      updatePayload.updateInfo.pose = {
        original: newChar.pose.original,
      }
    }

    if (newChar.voice) {
      updatePayload.updateInfo.voice = newChar.voice
    }

    if (newChar.language) {
      updatePayload.updateInfo.language = newChar.language
    }

    const res = await characterService.updateCharacter(updatePayload)
    // update the new char to the store
    createUniverseStore.updateChar(res)
    createUniverseStore.clearInEditCharacter()
  }
  catch (err) {
    console.log(err)
  }
}
</script>

<template>
  <ion-page>
    <common-header title="Character Settings">
      <character-setting-tip />
    </common-header>
    <ion-content>
      <div>
        <div class="card flex justify-between items-center">
          <div class="title">
            Name *
          </div>
          <ion-input
            v-if="inEditCharacter"
            v-model="inEditCharacter.charName"
            class="new-name"
            placeholder="Enter New Name"
          />
        </div>
        <div class="card">
          <div class="title">
            Description *
          </div>
          <ion-textarea
            v-if="inEditCharacter"
            v-model="inEditCharacter.charDescription"
            class="mt-2 text-area"
            placeholder="Enter description"
            autocomplete="on"
            autocorrect="on"
            autocapitalize="on"
            :rows="4"
            :maxlength="1000"
          />
        </div>
        <div class="card">
          <div class="title">
            Avatar
          </div>
          <div
            :class="`relative ${
              inEditCharacter?.complete ? 'bg-white' : 'bg-[#333]'
            } rd-3 m-auto mt-4 flex flex-col justify-center items-center`"
            :style="{ width: '154px', minHeight: '231px' }"
          >
            <signed-img
              v-if="inEditCharacter?.complete"
              class="mt-4"
              :src="inEditCharacter?.pose?.original || originalCharPose || ''"
              :style="{ width: '154px' }"
            />
            <loading-lottie v-else />
            <ion-button
              size="small"
              shape="round"
              class="absolute top-1 right-1 secondary-button"
              @click="
                () => {
                  if (loading) {
                    toastStore.setToast(
                      'Please wait for the character generated.',
                    );
                  }
                  else {
                    ionRouter.push(`/character/pose/${charId}`);
                  }
                }
              "
            >
              Edit
            </ion-button>
          </div>
        </div>
        <div class="card flex justify-between items-center">
          <div class="title">
            Voice
          </div>
          <div
            class="flex items-center gap-2 custom-color-yellow"
            @click="
              () => {
                if (loading) {
                  toastStore.setToast(
                    'Please wait for the character generated.',
                  );
                }
                else {
                  ionRouter.push(`/character-voice-select/${charId}`);
                }
              }
            "
          >
            {{ charVoiceModel ? charVoiceModel.displayName : "Select" }}
            <right-arrow-icon />
          </div>
        </div>
      </div>
      <div class="fixed bottom-4 w-full px-4">
        <ion-button
          class="w-full rounded-full overflow-hidden action-btn"
          :disabled="loading"
          @click="saveEdit"
        >
          Confirm
        </ion-button>
      </div>
    </ion-content>
  </ion-page>
</template>

